details.pau-detail summary{cursor:pointer;font-weight:800;color:var(--blue)}
.pau-steps{counter-reset:step}
.pau-step{counter-increment:step;position:relative;padding:12px 14px 12px 54px;margin:9px 0;background:#f4f9fb;border-radius:14px}
.pau-step:before{content:counter(step);position:absolute;left:14px;top:10px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:#0b5d7a;color:#fff;font-weight:800}
